using System;
using System.Drawing.Design;
using System.Windows.Forms;
using System.Windows.Forms.Design;

public class MyEditor : UITypeEditor
{
    public override object? EditValue(
        System.ComponentModel.ITypeDescriptorContext? context,
        IServiceProvider provider,
        object? value)
    {
        var editorService = provider?.GetService(typeof(IWindowsFormsEditorService))
            as IWindowsFormsEditorService;

        if (editorService == null)
            return value;

        // .NET 9 breaking change: DropDownControl(null) now throws ArgumentNullException.
        // Guard against null control before calling DropDownControl.
        var control = CreateEditorControl(value);
        if (control == null)
            return value;

        editorService.DropDownControl(control);
        return control.Tag;
    }

    private Control? CreateEditorControl(object? currentValue)
    {
        var listBox = new ListBox();
        listBox.Items.Add("Option A");
        listBox.Items.Add("Option B");
        listBox.Tag = currentValue;
        listBox.SelectedIndexChanged += (s, e) =>
        {
            if (s is ListBox lb && lb.SelectedItem != null)
                lb.Tag = lb.SelectedItem;
        };
        return listBox;
    }
}

